L["Frame and buttons"] = "Marco y botones"
L["Other windows keep the game's own look."] = "Las demás ventanas conservan el aspecto del juego."
L["How solid the whole map window is: lower shows the game world through it."] = "Qué tan opaca es toda la ventana del mapa: más bajo deja ver el mundo del juego a través de ella."
L["How dark the panel behind the arrow is. At 0, the arrow alone."] = "Qué tan oscuro es el panel detrás de la flecha. En 0, solo la flecha."
