L["Mark corners around the nodes to farm: %s adds one at the crosshair  ·  %s: undo  ·  %s: finish  |cff9d9d9d(%s cancels)|r"] = "Marca esquinas alrededor de los nodos para farmear: %s añade una en la mira  ·  %s: deshacer  ·  %s: terminar  |cff9d9d9d(%s cancela)|r"
L["Mark points at the crosshair with %s  ·  %s: undo  ·  %s: finish  |cff9d9d9d(%s cancels)|r"] = "Marca puntos en la mira con %s  ·  %s: deshacer  ·  %s: terminar  |cff9d9d9d(%s cancela)|r"
