L["%s: Add Corner   %s: Undo Corner   %s: Finish Area   %s: Cancel   %s: Zoom   %s: Pan"] = "%s: Añadir esquina   %s: Deshacer esquina   %s: Terminar área   %s: Cancelar   %s: Zoom   %s: Desplazar"
L["Add Corner"] = "Añadir esquina"
