L["Set Heights..."] = "Fijar alturas..."
L["Set Heights"] = "Fijar alturas"
L["End"] = "Final"
L["Heights Only"] = "Solo alturas"
L["The stretch from the foot to the top picked (none picked: the whole road). Start and end come from the road or the map's ground; type over them. The points between are spread evenly."] = "El tramo del pie a la cima elegidos (sin elegir: todo el camino). El inicio y el final vienen del camino o del suelo del mapa; escribe encima. Los puntos intermedios se reparten por igual."
L["|cffff6060Give it a start and an end height.|r"] = "|cffff6060Indica una altura inicial y una final.|r"
L["set the heights of that stretch (#%d): %s"] = "alturas de ese tramo fijadas (#%d): %s"
L["%s up"] = "%s arriba"
L["%s down"] = "%s abajo"
L["Edit Wall"] = "Editar muro"
L["Make a wall you drew a cliff: click this, then the wall on the map, and give the ground's height on each side (filled in from the map). Routes go round it from the low side and jump down from the high side when the drop is safe; level sides are open. Pick Start and Pick End: only that section. Undo takes it back. Click it again when done. (Shown with the wall tools)"] = "Convierte en acantilado un muro que dibujaste: haz clic aquí, luego en el muro del mapa, e indica la altura del suelo a cada lado (rellenada desde el mapa). Las rutas lo rodean desde el lado bajo y saltan desde el lado alto si la caída es segura; los lados al mismo nivel quedan abiertos. Elegir inicio y Elegir final: solo ese tramo. Deshacer lo revierte. Vuelve a hacer clic al terminar. (Se muestra con las herramientas de muros)"
L["no wall of yours there to edit (click on one you drew)"] = "no hay ningún muro tuyo ahí para editar (haz clic en uno que dibujaste)"
L["Cliff"] = "Acantilado"
L["Wall"] = "Muro"
L["Left side (blue)"] = "Lado izquierdo (azul)"
L["Right side (orange)"] = "Lado derecho (naranja)"
L["Pick Start"] = "Elegir inicio"
L["Pick End"] = "Elegir final"
L["Save Wall"] = "Guardar muro"
L["The ground's height on each side, filled in from the map: type over them. Level sides: open. Low to high: blocked. High to low: a jump down when it's safe, else blocked both ways."] = "La altura del suelo a cada lado, rellenada desde el mapa: escribe encima. Lados al mismo nivel: abierto. De bajo a alto: bloqueado. De alto a bajo: un salto si es seguro, si no bloqueado en ambos sentidos."
L["|cffff6060Give both sides a height.|r"] = "|cffff6060Indica una altura para ambos lados.|r"
L["saved your cliff (#%d): routes use it now. /agps draw undo takes it back."] = "acantilado guardado (#%d): las rutas ya lo usan. /agps draw undo lo deshace."
L["saved your wall (#%d): routes use it now. /agps draw undo takes it back."] = "muro guardado (#%d): las rutas ya lo usan. /agps draw undo lo deshace."
L["level: open"] = "al mismo nivel: abierto"
L["a safe jump down"] = "un salto seguro hacia abajo"
L["too high: blocked"] = "demasiado alto: bloqueado"
L["Cliff: left %d yd, right %d yd (%s)"] = "Acantilado: izquierda %d yd, derecha %d yd (%s)"
L["Swim"] = "Nado"
L["Swim %s"] = "Nada %s"
L["Swim %s to %s"] = "Nada %s hasta %s"
L["Start swimming"] = "Empieza a nadar"
L["start swimming"] = "empieza a nadar"
L["Leave the water"] = "Sal del agua"
L["leave the water"] = "sal del agua"
L["Swim, then %s in %s"] = "Nada y, en %2$s, %1$s"
L["Water walking"] = "Caminar sobre el agua"
L["Allow swimming"] = "Permitir nadar"
L["Routes may swim across rivers, lakes and the sea near the shore when that's faster, timed at swimming speed. Swims show as a wavy line; right-click one to go round by land on that trip. Off: routes go round by land wherever there's a way (an island is still swum to)."] = "Las rutas pueden cruzar a nado ríos, lagos y el mar cerca de la costa cuando es más rápido, contando la velocidad de nado. Los tramos a nado se ven como una línea ondulada; clic derecho en uno para ir por tierra en ese viaje. Desactivado: las rutas van por tierra siempre que haya camino (a una isla se sigue nadando)."
L["%s: as fast as on land."] = "%s: tan rápido como en tierra."
L["No way round by land: this swim stays."] = "No hay camino por tierra: este tramo a nado se queda."
L["Right-click: go round by land instead (this trip)"] = "Clic derecho: ir por tierra en su lugar (este viaje)"
