L["Your skill: Herbalism %d, Mining %d"] = "Tu habilidad: Herboristería %d, Minería %d"
L["Available is on: only the herbs and ore your skill can gather show on the map."] = "Disponibles está activado: en el mapa solo se muestran las hierbas y minerales que tu habilidad puede recolectar."
L["Showing the herbs and ore your skill can gather."] = "Se muestran las hierbas y minerales que tu habilidad puede recolectar."
L["Ore Only"] = "Solo minerales"
L["Herbs Only"] = "Solo hierbas"
L["Lists only the ore veins. Click again for every herb and vein."] = "Muestra solo las vetas. Vuelve a hacer clic para ver todas las hierbas y vetas."
L["Lists only the herbs. Click again for every herb and vein."] = "Muestra solo las hierbas. Vuelve a hacer clic para ver todas las hierbas y vetas."
