L["/agps draw eraser|zone|continent  (magic eraser, restore the zone or continent)"] = "/agps draw eraser|zone|continent  (borrador mágico, restaurar la zona o el continente)"
L["Circle size"] = "Tamaño del círculo"
L["Click Magic Eraser, then Shift + drag its circle over the road you drew: the map's own roads are back there. Ctrl + mouse wheel sizes it."] = "Haz clic en Borrador mágico y arrastra su círculo con Mayús sobre el camino que dibujaste: ahí vuelven los caminos del mapa. Ctrl + rueda del mouse cambia su tamaño."
L["Click a road: edit it"] = "Clic en un camino: editarlo"
